src/pipeline/attempt-usage-settlement.ts.source:
import type { Outcome } from "@qianliu/contracts";
import {
  type CreateUsageLedgerLineInput,
  summarizeLedgerUsageQuality,
  type FinalizeRejectedAttemptSettlementInput,
  type GatewayLedgerRepository,
  type PersistAttemptUsageAccountingInput,
} from "@qianliu/database";
import type { BillingRule } from "@qianliu/domain";

import { computeBillingFromRule, type BillingOutcome } from "./billing.js";
import { summarizePricingEvidence } from "./pricing-evidence.js";

export interface PersistAttemptUsageEvidenceInput {
  ledgerRepo: GatewayLedgerRepository;
  outcome: Outcome;
  requestId: string;
  enterpriseId: string;
  principalId: string;
  attemptId: string;
  attemptNo: number;
  attemptStartedAt: number;
  resourceId: string;
  resourceMode: "API" | "CODING_PLAN";
  upstreamModel: string;
  billingRule: BillingRule;
  monthlyAccounting?: { grantId: string; periodId: string; usageId: string; reservedEstimate: bigint; leaseId: string | null; attemptResult: PersistAttemptUsageAccountingInput["attempt_result"] };
  onPersistedQuotaUsage?: (usage: { raw: bigint; quality: string }) => void;
}

export interface FinalizeRejectedAttemptInput {
  ledgerRepo: GatewayLedgerRepository;
  requestId: string;
  enterpriseId: string;
  principalId: string;
  attemptId: string;
  attemptNo: number;
  resourceId: string;
  resourceMode: "API" | "CODING_PLAN";
  errorCode: string;
  attemptResult: PersistAttemptUsageAccountingInput["attempt_result"];
  quotaSettlements?: FinalizeRejectedAttemptSettlementInput["quota_settlements"];
  releaseLeaseIds?: string[];
  overage?: boolean;
}

export interface PersistRejectedAttemptEvidenceInput extends Omit<
  FinalizeRejectedAttemptInput,
  "errorCode" | "overage" | "attemptResult"
> {
  /** failover 分支必填；Attempt 结果与零事实、额度、租约一起提交。 */
  attemptResult?: PersistAttemptUsageAccountingInput["attempt_result"];
}

export interface FinalizeFailedRequestFromPersistedFactsInput {
  ledgerRepo: GatewayLedgerRepository;
  requestId: string;
  enterpriseId: string;
  principalId: string;
  errorClassification: string;
  errorCode: string;
  quotaSettlements?: FinalizeRejectedAttemptSettlementInput["quota_settlements"];
  releaseLeaseIds?: string[];
  overage?: boolean;
}

/**
 * 每个已创建的真实 Attempt 都冻结 usage + ledger：本函数只在 upstream caller
 * 实际执行后调用，因此 0 Token 不足以证明未触达上游——无计价证据时费用保持
 * UNKNOWN_COST，不得猜测为 0。确认未访问上游的 Attempt 由下方预上游 helper
 * 冻结为明确的零消费事实。
 */
export async function persistAttemptUsageEvidence(
  input: PersistAttemptUsageEvidenceInput,
): Promise<bigint | null> {
  const usage = input.outcome.usage;
  const billing = await resolveBilling(input, usage);
  const pricedApi = input.resourceMode === "API" && billing.apiCost !== null
    && (billing.currency === "CNY" || billing.currency === "USD");
  const evidence: CreateUsageLedgerLineInput = {
    usage: {
      ai_request_id: input.requestId,
      enterprise_id: input.enterpriseId,
      upstream_attempt_id: input.attemptId,
      provider_resource_id: input.resourceId,
      input_tokens: BigInt(usage.input),
      output_tokens: BigInt(usage.output),
      cache_tokens: BigInt(usage.cache),
      reasoning_tokens: BigInt(usage.reasoning ?? 0),
      usage_quality: usage.quality,
      dedup_key: `${input.requestId}:attempt${input.attemptNo}`,
    },
    ledger_line: {
      ai_request_id: input.requestId,
      enterprise_id: input.enterpriseId,
      upstream_attempt_id: input.attemptId,
      provider_resource_id: input.resourceId,
      principal_id: input.principalId,
      resource_mode: input.resourceMode,
      raw_input_tokens: BigInt(usage.input),
      raw_output_tokens: BigInt(usage.output),
      raw_cache_tokens: BigInt(usage.cache),
      raw_reasoning_tokens: BigInt(usage.reasoning ?? 0),
      deducted_quota: billing.deductedQuota === null ? null : BigInt(billing.deductedQuota),
      api_cost: pricedApi ? billing.apiCost : null,
      api_cost_currency: pricedApi ? billing.currency as "CNY" | "USD" : null,
      api_cost_status: input.resourceMode === "CODING_PLAN" ? "NOT_APPLICABLE"
        : pricedApi ? "PRICED_USAGE" : "UNKNOWN_COST",
      settled_at: new Date(),
      usage_quality: usage.quality,
      billing_rule_id: billing.ruleId,
      rule_version: billing.ruleVersion,
      multiplier: billing.multiplier,
      billing_rule_snapshot: billing.ruleSnapshot ? { ...billing.ruleSnapshot,
        pricingAt: new Date(input.attemptStartedAt).toISOString(), apiCost: billing.apiCost,
        deductedQuota: billing.deductedQuota, usageQuality: usage.quality } : null,
    },
  };
  const monthly = input.monthlyAccounting;
  const actual = input.resourceMode === "API" ? BigInt(usage.input) + BigInt(usage.output)
    : BigInt(billing.deductedQuota ?? 0);
  const unknown = usage.quality === "UNKNOWN"
    || (!hasMeasuredTokens(input.outcome) && usage.quality !== "PROVIDER_REPORTED")
    || (input.resourceMode === "CODING_PLAN" && billing.deductedQuota === null);
  const settlement = monthly
    ? await input.ledgerRepo.persistAttemptUsageAccountingIfAbsent({ ...evidence,
      attempt_result: monthly.attemptResult,
      quota_settlements: [{ grant_id: monthly.grantId, period_id: monthly.periodId, usage_id: monthly.usageId,
        reserved_estimate: monthly.reservedEstimate, actual_deducted: actual,
        usage_status: unknown ? "UNKNOWN" : undefined, usage_quality: usage.quality }],
      release_lease_ids: monthly.leaseId ? [monthly.leaseId] : [],
    })
    : await input.ledgerRepo.createUsageAndLedgerLineIfAbsent(evidence);
  input.onPersistedQuotaUsage?.({
    raw: BigInt(settlement.line.raw_input_tokens) + BigInt(settlement.line.raw_output_tokens),
    quality: settlement.line.usage_quality === "UNKNOWN"
      || (BigInt(settlement.line.raw_input_tokens) + BigInt(settlement.line.raw_output_tokens) === 0n
        && settlement.line.usage_quality !== "PROVIDER_REPORTED") ? "UNKNOWN" : settlement.line.usage_quality,
  });
  return settlement.line.deducted_quota === null
    ? null
    : BigInt(settlement.line.deducted_quota);
}

/**
 * 已创建 Attempt、但最终授权栅栏在上游前拒绝时，冻结明确的零消费事实。
 * failover 分支同时原子完成 Attempt/额度/租约；terminal 分支仍交给 finalize 发布终态。
 */
export async function persistRejectedAttemptBeforeUpstreamEvidence(
  input: PersistRejectedAttemptEvidenceInput,
): Promise<void> {
  const evidence = rejectedAttemptEvidence(input);
  if (input.attemptResult) {
    await input.ledgerRepo.persistAttemptUsageAccountingIfAbsent({
      ...evidence,
      attempt_result: input.attemptResult,
      quota_settlements: input.quotaSettlements,
      release_lease_ids: input.releaseLeaseIds,
    });
    return;
  }
  if ((input.quotaSettlements?.length ?? 0) > 0 || (input.releaseLeaseIds?.length ?? 0) > 0) {
    throw new Error("nonterminal_attempt_result_required");
  }
  await input.ledgerRepo.createUsageAndLedgerLineIfAbsent(evidence);
}

function rejectedAttemptEvidence(input: Pick<
  FinalizeRejectedAttemptInput,
  "requestId" | "enterpriseId" | "principalId" | "attemptId" | "attemptNo"
  | "resourceId" | "resourceMode"
>): CreateUsageLedgerLineInput {
  return {
    usage: {
      ai_request_id: input.requestId,
      enterprise_id: input.enterpriseId,
      upstream_attempt_id: input.attemptId,
      provider_resource_id: input.resourceId,
      input_tokens: 0n,
      output_tokens: 0n,
      cache_tokens: 0n,
      reasoning_tokens: 0n,
      usage_quality: "UNKNOWN",
      dedup_key: `${input.requestId}:attempt${input.attemptNo}`,
    },
    ledger_line: {
      ai_request_id: input.requestId,
      enterprise_id: input.enterpriseId,
      upstream_attempt_id: input.attemptId,
      provider_resource_id: input.resourceId,
      principal_id: input.principalId,
      resource_mode: input.resourceMode,
      raw_input_tokens: 0n,
      raw_output_tokens: 0n,
      raw_cache_tokens: 0n,
      raw_reasoning_tokens: 0n,
      deducted_quota: null,
      // 已确认未访问上游：API 成本是精确 0，不是“未知”。否则后续成功
      // Attempt 的真实费用会被请求级未知行吞掉，错误聚合成 0。
      api_cost: input.resourceMode === "API" ? "0.00000000" : null,
      api_cost_currency: null,
      api_cost_status: input.resourceMode === "API"
        ? "CONFIRMED_ZERO_NO_UPSTREAM" : "NOT_APPLICABLE",
      settled_at: new Date(),
      usage_quality: "UNKNOWN",
      billing_rule_id: null,
      rule_version: null,
      multiplier: null,
      billing_rule_snapshot: null,
    },
  };
}

/** Attempt、零消费事实、请求失败终态及额度／租约由数据库一次提交。 */
export async function finalizeRejectedAttemptBeforeUpstream(
  input: FinalizeRejectedAttemptInput,
): Promise<void> {
  await input.ledgerRepo.finalizeRejectedAttemptSettlementIfAbsent({
    ...rejectedAttemptEvidence(input),
    attempt_result: input.attemptResult,
    overage: input.overage ?? false,
    error_classification: input.attemptResult.error_classification ?? "DOWNSTREAM_AUTH_OR_QUOTA",
    error_code: input.errorCode,
    quota_settlements: input.quotaSettlements,
    release_lease_ids: input.releaseLeaseIds,
  });
}

/**
 * Attempt 已经冻结账本事实、但后续候选在创建 Attempt 前耗尽时，不能绕过请求级
 * 原子终结直接写 FAILED。仅在确有 ledger_line 时聚合并发布 transaction；额度和
 * 租约只接收尚未结算的 pending 项，已由非终态 Attempt 清算的资源不会重复处理。
 */
export async function finalizeFailedRequestFromPersistedFactsIfAny(
  input: FinalizeFailedRequestFromPersistedFactsInput,
): Promise<boolean> {
  const lines = await input.ledgerRepo.listLedgerLines(input.requestId);
  if (lines.length === 0) return false;
  const attempts = await input.ledgerRepo.listAttempts(input.requestId);
  const pricing = summarizePricingEvidence(lines);
  await input.ledgerRepo.finalizeLedgerSettlementIfAbsent({
    ai_request_id: input.requestId,
    enterprise_id: input.enterpriseId,
    principal_id: input.principalId,
    total_input_tokens: lines.reduce((sum, line) => sum + BigInt(line.raw_input_tokens), 0n),
    total_output_tokens: lines.reduce((sum, line) => sum + BigInt(line.raw_output_tokens), 0n),
    total_cache_tokens: lines.reduce((sum, line) => sum + BigInt(line.raw_cache_tokens), 0n),
    total_reasoning_tokens: lines.reduce(
      (sum, line) => sum + BigInt(line.raw_reasoning_tokens), 0n,
    ),
    total_deducted_quota: lines.reduce(
      (sum, line) => sum + BigInt(line.deducted_quota ?? 0), 0n,
    ),
    // F-020：混合币种或费用未知 → 单一原币总额不可计算（UNKNOWN_COST + NULL）。
    total_api_cost: pricing.mixedApiCostCurrency || pricing.unknownApiCost
      ? null
      : (pricing.actualCost ?? "0.00000000"),
    api_cost_status: pricing.mixedApiCostCurrency ? "UNKNOWN_COST" : undefined,
    usage_quality: summarizeLedgerUsageQuality(lines),
    attempt_count: attempts.length,
    overage: input.overage ?? false,
    request_status: "FAILED",
    error_classification: input.errorClassification,
    error_code: input.errorCode,
    quota_settlements: input.quotaSettlements,
    release_lease_ids: input.releaseLeaseIds,
  });
  return true;
}

async function resolveBilling(
  input: PersistAttemptUsageEvidenceInput,
  usage: Outcome["usage"],
): Promise<BillingOutcome> {
  if (usage.quality === "UNKNOWN"
    || (!hasMeasuredTokens(input.outcome) && usage.quality !== "PROVIDER_REPORTED")) {
    return {
      apiCost: null,
      currency: null,
      deductedQuota: null,
      ruleId: null,
      ruleVersion: null,
      multiplier: null,
      ruleSnapshot: null,
    };
  }
  return computeBillingFromRule(
    input.billingRule,
    input.resourceMode,
    input.attemptStartedAt,
    usage,
  );
}

function hasMeasuredTokens(outcome: Outcome): boolean {
  const usage = outcome.usage;
  return usage.input > 0
    || usage.output > 0
    || usage.cache > 0
    || (usage.reasoning ?? 0) > 0;
}

src/pipeline/pipeline-settlement.ts.source:
import { summarizeLedgerUsageQuality, QuotaBlockRepository } from "@qianliu/database";
import {
  availabilitySignalSummary,
  clampProviderWindowRecoveryAt,
  parseQuotaBlockState,
  type ErrorClassification,
} from "@qianliu/domain";
import {
  calculateDispatchSaving,
  dispatchCounterfactualEvidence,
  dispatchSavingFields,
} from "./billing.js";
import { summarizePricingEvidence } from "./pricing-evidence.js";
import { attributeQuotaExhaustion } from "./quota-exhaustion-attribution.js";
import {
  buildQuotaWindowPresentation,
  canonicalCodingPlanProvider,
  presentationFromStoredBlock,
} from "./quota-window-presentation.js";
import {
  latestProviderQuotaResetAt,
  mapToClassification,
  runBestEffort,
} from "./runtime-controls.js";
import type { PipelineContext, PipelineExecutionState } from "./real-pipeline-types.js";

interface FrozenLedgerSettlement {
  transactionApiCost: string | null;
  actualCostCurrency: string | null;
  transactionUsage: { input: number; output: number; cache: number } | null;
  actualPricingEvidenceComplete: boolean;
  actualPricingEvidence: Array<Record<string, unknown>>;
}

/** 冻结请求级账本终态（F-020：混合币种/费用未知 → UNKNOWN_COST + NULL 总额）。 */
async function freezeRequestLedgerSettlement(
  context: PipelineContext,
  state: PipelineExecutionState,
): Promise<FrozenLedgerSettlement> {
  const { deps, requestId, principal, principalId } = context;
  const lines = await deps.ledgerRepo.listLedgerLines(requestId);
  const persistedAttempts = await deps.ledgerRepo.listAttempts(requestId);
  const sumIn = lines.reduce((acc, line) => acc + BigInt(line.raw_input_tokens), 0n);
  const sumOut = lines.reduce((acc, line) => acc + BigInt(line.raw_output_tokens), 0n);
  const sumCache = lines.reduce((acc, line) => acc + BigInt(line.raw_cache_tokens), 0n);
  const sumReasoning = lines.reduce((acc, line) => acc + BigInt(line.raw_reasoning_tokens), 0n);
  const sumDeducted = lines.reduce((acc, line) => acc + BigInt(line.deducted_quota ?? 0), 0n);
  const pricingEvidence = summarizePricingEvidence(lines);
  const usageQuality = summarizeLedgerUsageQuality(lines);
  await deps.ledgerRepo.finalizeLedgerSettlementIfAbsent({
    ai_request_id: requestId,
    enterprise_id: principal.enterpriseId,
    principal_id: principalId,
    total_input_tokens: sumIn,
    total_output_tokens: sumOut,
    total_cache_tokens: sumCache,
    total_reasoning_tokens: sumReasoning,
    total_deducted_quota: sumDeducted,
    total_api_cost: pricingEvidence.mixedApiCostCurrency || pricingEvidence.unknownApiCost
      ? null
      : (pricingEvidence.actualCost ?? "0.00000000"),
    api_cost_status: pricingEvidence.mixedApiCostCurrency ? "UNKNOWN_COST" : undefined,
    usage_quality: usageQuality,
    attempt_count: persistedAttempts.length,
    overage: state.requestOverage,
    request_status: state.finalOutcome!.committed && !state.finalOutcome!.error ? "SUCCEEDED" : "FAILED",
    error_classification: state.finalOutcome!.error
      ? (state.finalOutcomeClassification ?? mapToClassification(state.finalOutcome!))
      : null,
    error_code: state.finalOutcome!.error ?? null,
    quota_settlements: state.pendingQuotaSettlements,
    release_lease_ids: state.pendingLeaseIds,
  });
  return {
    transactionApiCost: pricingEvidence.actualCost,
    actualCostCurrency: pricingEvidence.actualCostCurrency,
    transactionUsage: { input: Number(sumIn), output: Number(sumOut), cache: Number(sumCache) },
    actualPricingEvidenceComplete: pricingEvidence.complete,
    actualPricingEvidence: pricingEvidence.items,
  };
}

/** 冻结请求级账本并在终态之后执行资源健康与 Runtime Assurance 副作用。 */
export async function settlePipelineRequest(
  context: PipelineContext,
  state: PipelineExecutionState,
): Promise<void> {
  const { deps, request, requestId, principal, principalId, requestStartedAt } = context;
  let frozen: FrozenLedgerSettlement | null = null;
  if (state.finalOutcome) {
    frozen = await freezeRequestLedgerSettlement(context, state);
    if (deps.dispatchRepo && state.dispatchFinalAction !== null && state.dispatchDispatchInput !== null) {
      await runBestEffort(request.log, "enrich post-settlement dispatch evidence", async () => {
        const { counterfactualBilling, counterfactualCost, saving } = await calculateDispatchSaving({
          finalAction: state.dispatchFinalAction!,
          switchTargetId: state.dispatchSwitchTargetId,
          baselineCandidate: state.dispatchBaselineCandidate,
          baselineRule: state.dispatchBaselineRule ?? null,
          invokedResourceIds: state.invokedResourceIds,
          transactionUsage: frozen!.transactionUsage,
          actualCost: frozen!.transactionApiCost,
          actualCostCurrency: frozen!.actualCostCurrency,
          actualPricingEvidenceComplete: frozen!.actualPricingEvidenceComplete,
          ledgerRepo: deps.ledgerRepo,
          enterpriseId: principal.enterpriseId,
          requestStartedAt,
        });
        const evidence = {
          enterpriseId: principal.enterpriseId,
          aiRequestId: requestId,
          dispatchInput: {
            now: state.dispatchDispatchInput!.now,
            unifiedModel: state.dispatchDispatchInput!.unifiedModel,
            selectedResourceId: state.dispatchDispatchInput!.selectedResourceId,
            resourceMode: state.dispatchDispatchInput!.resourceMode,
            priceMultiplier: state.dispatchDispatchInput!.priceMultiplier,
            remainingQuotaRatio: state.dispatchDispatchInput!.remainingQuotaRatio,
            forecastExhaustRisk: state.dispatchDispatchInput!.forecastExhaustRisk,
            principalId: state.dispatchDispatchInput!.principalId,
            matchedTimezone: state.dispatchMatchedPolicy?.matchTimezone ?? null,
            matchedDaysOfWeek: state.dispatchMatchedPolicy?.matchDaysOfWeek ?? null,
            matchedStartTime: state.dispatchMatchedPolicy?.matchStartTime ?? null,
            matchedEndTime: state.dispatchMatchedPolicy?.matchEndTime ?? null,
            ...dispatchCounterfactualEvidence(state.dispatchBaselineCandidate, counterfactualBilling),
            executedResourceIds: [...state.invokedResourceIds],
            usageEvidence: frozen!.transactionUsage,
            actualPricingEvidence: frozen!.actualPricingEvidence,
            savingCalculationVersion: "pool-021-v1",
          },
          counterfactualCost,
          actualCost: frozen!.transactionApiCost,
          ...dispatchSavingFields(saving),
        };
        try {
          await deps.dispatchRepo!.enrichDecisionSettlementEvidence(evidence);
        } catch {
          await deps.dispatchRepo!.enrichDecisionSettlementEvidence(evidence);
        }
      });
    }
  }

  for (const effect of state.deferredResourceEffects) {
    const { outcome, classification, resource, probeLease } = effect;
    const settlementNow = new Date();
    // CPQW（计划§5/§7）：CP 明确窗口/套餐耗尽 → 同一资源优先事务保存 block、
    // EXHAUSTED 与绑定 incident 的额度事件；普通 recordSignal/recordFailure 不再重复执行。
    const cpDefiniteExhaustion = resource.mode === "CODING_PLAN"
      && (outcome.upstreamErrorKind === "WINDOW_EXHAUSTED" || outcome.upstreamErrorKind === "QUOTA_EXHAUSTED");
    if (cpDefiniteExhaustion) {
      await runBestEffort(request.log, "settle coding plan quota exhaustion", async () => {
        const observations = await attributeQuotaExhaustion({
          db: deps.db,
          enterpriseId: principal.enterpriseId,
          resourceId: resource.resourceId,
          outcome,
          now: settlementNow,
        });
        const quotaBlockRepo = new QuotaBlockRepository(deps.db);
        const fault = await quotaBlockRepo.recordCodingPlanExhaustionFault({
          resourceId: resource.resourceId,
          expectedResourceVersion: effect.resourceVersion,
          expectedCredentialVersion: effect.credentialVersion,
          observations,
          now: settlementNow,
          runtimeAssurance: deps.runtimeAssuranceRepo && resource.providerId
            ? {
                mode: deps.runtimeAssuranceMode ?? "OBSERVE",
                wecomNotify: deps.runtimeAssuranceWecomNotify ?? false,
              }
            : null,
          signal: {
            providerId: resource.providerId ?? "",
            unifiedModelId: resource.unifiedModelId ?? null,
            upstreamModel: resource.upstreamModel,
            upstreamCode: outcome.upstreamCode ?? outcome.error ?? null,
            sanitizedSummary: availabilitySignalSummary("QUOTA_EXHAUSTED"),
            aiRequestId: requestId,
            principalId,
          },
        });
        // 复审缺陷 3：生产 code 可能大写（Kimi/Zhipu），统一 canonical 化。
        const providerCode = canonicalCodingPlanProvider(resource.providerCode);
        if (fault.status === "COMMITTED" && fault.block) {
          state.quotaWindowPresentation = buildQuotaWindowPresentation({
            providerCode,
            windows: fault.block.windows.map((window) => ({
              type: window.type, resetAt: window.resetAt, resetSource: window.resetSource,
            })),
            unknownWindow: fault.block.unknownWindow,
            now: settlementNow,
          });
        } else {
          // Token 失配（迟到失败/轮换后新故障）：读当前记录呈现，不覆盖新事实。
          const row = await deps.poolRepo.getResource(resource.resourceId);
          const stored = row?.quota_block_state ? parseQuotaBlockState(row.quota_block_state) : null;
          state.quotaWindowPresentation = stored
            ? presentationFromStoredBlock({ block: stored, providerCode, now: settlementNow })
            : null;
        }
      });
      if (probeLease) {
        await runBestEffort(request.log, "release post-settlement half-open probe", () =>
          deps.poolRepo.releaseHalfOpenProbe(resource.resourceId, probeLease.acquiredAt));
      }
      continue;
    }
    if (outcome.upstreamErrorKind === "WINDOW_EXHAUSTED") {
      const recoveryCheckedAt = Date.now();
      const recoverAt = outcome.recoverAt ?? await latestProviderQuotaResetAt(
        deps.db, principal.enterpriseId, resource.resourceId, new Date(), "FIVE_HOUR",
      );
      if (recoverAt) {
        const parsedRecoverAt = Date.parse(recoverAt);
        if (Number.isFinite(parsedRecoverAt)) {
          const boundedRecoverAt = clampProviderWindowRecoveryAt(recoveryCheckedAt, parsedRecoverAt);
          outcome.recoverAt = new Date(boundedRecoverAt).toISOString();
          outcome.retryAfterMs = boundedRecoverAt - recoveryCheckedAt;
        }
      }
    }
    const availabilitySignal = outcome.unifiedAvailabilitySignal;
    const providerId = resource.providerId;
    if (outcome.error && availabilitySignal && deps.runtimeAssuranceRepo && providerId) {
      const signalResult = await runBestEffort(
        request.log,
        "record post-settlement runtime assurance signal",
        () => deps.runtimeAssuranceRepo!.recordSignal({
          enterpriseId: principal.enterpriseId,
          providerId,
          providerResourceId: resource.resourceId,
          unifiedModelId: resource.unifiedModelId ?? null,
          upstreamModel: resource.upstreamModel,
          signal: availabilitySignal,
          upstreamCode: outcome.upstreamCode ?? outcome.error,
          sanitizedSummary: availabilitySignalSummary(availabilitySignal),
          upstreamRecoverAt: outcome.recoverAt ? new Date(outcome.recoverAt) : null,
          aiRequestId: requestId,
          principalId,
          now: new Date(requestStartedAt),
          mode: deps.runtimeAssuranceMode ?? "OBSERVE",
          wecomNotify: deps.runtimeAssuranceWecomNotify ?? false,
        }),
      );
      if (signalResult) state.finalSignalResult = signalResult;
    }
    if (outcome.committed && !outcome.error) {
      await runBestEffort(request.log, "record post-settlement resource success", () =>
        deps.poolRepo.recordSuccess(resource.resourceId));
    } else if (classification) {
      await runBestEffort(request.log, "record post-settlement resource failure", () =>
        deps.poolRepo.recordFailure(
          resource.resourceId,
          classification as ErrorClassification,
          new Date(),
          {
            upstreamModel: resource.upstreamModel,
            upstreamConfigHash: outcome.upstreamConfigHash,
            retryAfterMs: outcome.retryAfterMs,
            cooldownUntil: outcome.upstreamErrorKind === "WINDOW_EXHAUSTED" && outcome.recoverAt
              ? new Date(outcome.recoverAt).getTime()
              : undefined,
          },
        ));
    }
    if (probeLease) {
      await runBestEffort(request.log, "release post-settlement half-open probe", () =>
        deps.poolRepo.releaseHalfOpenProbe(resource.resourceId, probeLease.acquiredAt));
    }
  }
}

