      resourceId: "resource-api", resourceMode: "API", errorCode: "principal_grant_required",
      attemptResult: {
        http_status: 403, response_committed: false, finished_at: new Date("2026-09-03T00:00:00Z"),
        error_classification: "DOWNSTREAM_AUTH_OR_QUOTA", error_code: "principal_grant_required",
        switch_reason: null,
      },
    });
    expect(finalizeRejectedAttemptSettlementIfAbsent).toHaveBeenCalledWith(expect.objectContaining({
      ledger_line: expect.objectContaining({
        api_cost: "0.00000000", api_cost_currency: null,
        api_cost_status: "CONFIRMED_ZERO_NO_UPSTREAM", settled_at: expect.any(Date),
      }),
    }));
  });

  it("failover 已有结算事实时聚合发布 FAILED，且不重复结算已释放资源", async () => {
    const finalizeLedgerSettlementIfAbsent = vi.fn().mockResolvedValue(undefined);
    const ledgerRepo = {
      listLedgerLines: vi.fn().mockResolvedValue([{
        raw_input_tokens: 12n,
        raw_output_tokens: 4n,
        raw_cache_tokens: 2n,
        raw_reasoning_tokens: 1n,
        deducted_quota: null,
        api_cost: "0.12345678",
        resource_mode: "API",
        usage_quality: "PROVIDER_REPORTED",
        provider_resource_id: "resource-1",
        billing_rule_id: "rule-1",
        rule_version: "v1",
        billing_rule_snapshot: {},
      }, {
        raw_input_tokens: 3n,
        raw_output_tokens: 5n,
        raw_cache_tokens: 1n,
        raw_reasoning_tokens: 2n,
        deducted_quota: 7n,
        api_cost: null,
        resource_mode: "CODING_PLAN",
        usage_quality: "UNKNOWN",
        provider_resource_id: "resource-2",
        billing_rule_id: "rule-2",
        rule_version: "v2",
        billing_rule_snapshot: {},
      }]),
      listAttempts: vi.fn().mockResolvedValue([{ id: "attempt-1" }, { id: "attempt-2" }]),
      finalizeLedgerSettlementIfAbsent,
    } as unknown as GatewayLedgerRepository;

    await expect(finalizeFailedRequestFromPersistedFactsIfAny({
      ledgerRepo,
      requestId: "request-1",
      enterpriseId: "enterprise-1",
      principalId: "principal-1",
      errorClassification: "DOWNSTREAM_AUTH_OR_QUOTA",
      errorCode: "principal_grant_required",
      overage: true,
    })).resolves.toBe(true);

    expect(finalizeLedgerSettlementIfAbsent).toHaveBeenCalledTimes(1);
    expect(finalizeLedgerSettlementIfAbsent).toHaveBeenCalledWith(expect.objectContaining({
      ai_request_id: "request-1",
      total_input_tokens: 15n,
      total_output_tokens: 9n,
      total_cache_tokens: 3n,
      total_reasoning_tokens: 3n,
      total_deducted_quota: 7n,
      total_api_cost: "0.12345678",
      usage_quality: "MIXED:PROVIDER_REPORTED+UNKNOWN",
      attempt_count: 2,
      request_status: "FAILED",
      error_classification: "DOWNSTREAM_AUTH_OR_QUOTA",
      error_code: "principal_grant_required",
      overage: true,
      quota_settlements: undefined,
      release_lease_ids: undefined,
    }));
  });

  it("仅有套餐零事实时 API 成本回落为零且默认不标记超额", async () => {
    const finalizeLedgerSettlementIfAbsent = vi.fn().mockResolvedValue(undefined);
    const ledgerRepo = {
      listLedgerLines: vi.fn().mockResolvedValue([{
        raw_input_tokens: 0n,
        raw_output_tokens: 0n,
        raw_cache_tokens: 0n,
        raw_reasoning_tokens: 0n,
        deducted_quota: null,
        api_cost: null,
        resource_mode: "CODING_PLAN",
        usage_quality: "UNKNOWN",
        provider_resource_id: "resource-1",
        billing_rule_id: null,
        rule_version: null,
        billing_rule_snapshot: null,
      }]),
      listAttempts: vi.fn().mockResolvedValue([{ id: "attempt-1" }]),
      finalizeLedgerSettlementIfAbsent,
    } as unknown as GatewayLedgerRepository;

    await finalizeFailedRequestFromPersistedFactsIfAny({
      ledgerRepo,
      requestId: "request-2",
      enterpriseId: "enterprise-1",
      principalId: "principal-1",
      errorClassification: "NO_HEALTHY_CANDIDATE",
      errorCode: "no_healthy_candidate",
    });

    expect(finalizeLedgerSettlementIfAbsent).toHaveBeenCalledWith(expect.objectContaining({
      total_api_cost: "0.00000000",
      overage: false,
    }));
  });

  it("尚无账本事实时保留普通状态更新路径", async () => {
    const finalizeLedgerSettlementIfAbsent = vi.fn();
    const ledgerRepo = {
      listLedgerLines: vi.fn().mockResolvedValue([]),
      listAttempts: vi.fn(),
      finalizeLedgerSettlementIfAbsent,
    } as unknown as GatewayLedgerRepository;

    await expect(finalizeFailedRequestFromPersistedFactsIfAny({
      ledgerRepo,
      requestId: "request-2",
      enterpriseId: "enterprise-1",
      principalId: "principal-1",
      errorClassification: "NO_HEALTHY_CANDIDATE",
      errorCode: "no_healthy_candidate",
    })).resolves.toBe(false);
    expect(ledgerRepo.listAttempts).not.toHaveBeenCalled();
    expect(finalizeLedgerSettlementIfAbsent).not.toHaveBeenCalled();
  });
});

it("rejects before upstream with a definite zero and defaults omitted overage and classification", async () => {
  const finalize = vi.fn().mockResolvedValue(undefined);
  await finalizeRejectedAttemptBeforeUpstream({
    ledgerRepo: { finalizeRejectedAttemptSettlementIfAbsent: finalize } as unknown as GatewayLedgerRepository,
    requestId: "request-defaults", enterpriseId: "enterprise-1", principalId: "principal-1",
    attemptId: "attempt-defaults", attemptNo: 1, resourceId: "resource-1", resourceMode: "API",
    errorCode: "dispatch_changed_before_upstream",
    attemptResult: { http_status: 403, response_committed: false, finished_at: new Date("2026-11-01T00:00:00Z"),
      error_classification: null, error_code: "dispatch_changed_before_upstream", switch_reason: null },
  });
  expect(finalize).toHaveBeenCalledWith(expect.objectContaining({
    overage: false, error_classification: "DOWNSTREAM_AUTH_OR_QUOTA",
    ledger_line: expect.objectContaining({ api_cost: "0.00000000", api_cost_status: "CONFIRMED_ZERO_NO_UPSTREAM" }),
  }));
});

src/auth/current-model-authorization.mut.source:
import { describe, expect, it } from "vitest";

import {
  getCurrentInvocationAuthorization,
  hasCurrentInvocationAuthorization,
} from "./current-model-authorization.js";

type Comparison = [unknown, unknown, unknown];

interface AuthorizationTrace {
  comparisons: Comparison[];
  innerJoins: string[];
  innerJoinRefs: Comparison[];
  isolationLevels: string[];
  selectFrom: unknown[];
  selections: unknown[];
  whereRefs: Comparison[];
}

const DEFAULT_BILLING_RULE = {
  id: "billing-rule", rule_type: "API_PRICE", rule_version: "v1",
  provider_resource_id: "resource", upstream_model: "kimi-k3",
  effective_from: new Date(0), effective_to: null, timezone: "Asia/Shanghai",
  days_of_week: null, start_time: null, end_time: null, time_windows: null,
  multiplier: null, cache_hit_price: "0.000001", cache_miss_price: "0.000001",
  output_price: "0.000001", currency: "CNY", priority: 100,
};

class AuthorizationQuery {
  constructor(
    private readonly trace: AuthorizationTrace,
    private readonly result: Record<string, unknown> | null,
    private readonly table: string,
    private readonly billingRules: unknown[] = [DEFAULT_BILLING_RULE],
  ) {}

  innerJoin(table: string, left: unknown, _right?: unknown) {
    this.trace.innerJoins.push(table);
    if (typeof left === "function") {
      const join = {
        onRef: (_left: unknown, _operator: unknown, _right: unknown) => join,
        on: (_left: unknown, _operator: unknown, _right: unknown) => join,
      };
      left(join);
    } else {
      this.trace.innerJoinRefs.push([left, "=", _right]);
    }
    return this;
  }

  select(selection: unknown) {
    this.trace.selections.push(selection);
    return this;
  }
  distinct() { return this; }
  whereRef(left: unknown, operator: unknown, right: unknown) {
    this.trace.whereRefs.push([left, operator, right]);
    return this;
  }

  where(column: unknown, operator?: unknown, value?: unknown) {
    if (typeof column === "function") column(this.expressionBuilder());
    else this.trace.comparisons.push([column, operator, value]);
    return this;
  }

  private expressionBuilder() {
    const builder = Object.assign(
      (column: unknown, operator: unknown, value: unknown) => {
        const comparison: Comparison = [column, operator, value];
        this.trace.comparisons.push(comparison);
        return comparison;
      },
      {
        and: (values: unknown[]) => values,
        or: (values: unknown[]) => values,
        not: (value: unknown) => value,
        exists: (value: unknown) => value,
        ref: (value: unknown) => ({ ref: value }),
        selectFrom: (table: string) => {
          this.trace.selectFrom.push(table);
          return new AuthorizationQuery(this.trace, this.result, table, this.billingRules);
        },
      },
    );
    return builder;
  }

  executeTakeFirst() {
    return Promise.resolve(this.result);
  }

  execute() {
    if (this.table === "billing_rule") return Promise.resolve(this.billingRules);
    if (this.table !== "principal_key") return Promise.resolve([]);
    if (this.result === null) return Promise.resolve([]);
    return Promise.resolve(this.billingRules.map((rule) => {
      const billing = rule as typeof DEFAULT_BILLING_RULE;
      return {
        ...(this.result as Record<string, unknown>),
        billing_rule_id: billing.id,
        billing_rule_type: billing.rule_type,
        billing_rule_version: billing.rule_version,
        billing_provider_resource_id: billing.provider_resource_id,
        billing_upstream_model: billing.upstream_model,
        billing_effective_from: billing.effective_from,
        billing_effective_to: billing.effective_to,
        billing_timezone: billing.timezone,
        billing_days_of_week: billing.days_of_week,
        billing_start_time: billing.start_time,
        billing_end_time: billing.end_time,
        billing_time_windows: billing.time_windows,
        billing_multiplier: billing.multiplier,
        billing_cache_hit_price: billing.cache_hit_price,
        billing_cache_miss_price: billing.cache_miss_price,
        billing_output_price: billing.output_price,
        billing_currency: billing.currency,
        billing_priority: billing.priority,
      };
    }));
  }
}

function fakeDb(
  result: Record<string, unknown> | null,
  billingRules: unknown[] = [DEFAULT_BILLING_RULE],
) {
  const trace: AuthorizationTrace = {
    comparisons: [], innerJoins: [], innerJoinRefs: [], isolationLevels: [], selectFrom: [], selections: [], whereRefs: [],
  };
  const db = {
    selectFrom: (table: string) => {
        trace.selectFrom.push(table);
        return new AuthorizationQuery(trace, result, table, billingRules);
      },
    transaction: () => ({
      setIsolationLevel: (level: string) => {
        trace.isolationLevels.push(level);
        return ({
        execute: (work: (trx: unknown) => Promise<unknown>) => work(db),
        });
      },
    }),
  };
  return { trace, db };
}

const AUTH_INPUT = {
  enterpriseId: "enterprise",
  principalId: "principal",
  keyId: "key",
  modelAlias: "ql-k3",
  providerCode: "kimi",
  resourceId: "resource",
  upstreamModel: "kimi-k3",
  now: new Date("2026-08-09T12:00:00.000Z"),
};

describe("POOL-039 current authorization mutation contract", () => {
  it("keeps the exact Grant alias tied to the current unified model alias", async () => {
    const result = {
      allowed_model_ids: ["model-id"], expires_at: null, model_id: "model-id", resource_mode: "API",
    };
    const { db, trace } = fakeDb(result);
    const now = AUTH_INPUT.now;

    await expect(getCurrentInvocationAuthorization(db as never, AUTH_INPUT))
      .resolves.toMatchObject({ billingRule: { id: "billing-rule", ruleVersion: "v1" } });
    expect(trace.isolationLevels).toEqual(["repeatable read"]);

    expect(trace.selectFrom).toEqual(["principal_key", "principal_provider_disabled_model"]);
    expect(trace.innerJoins).toContain("billing_rule");
    expect(trace.innerJoinRefs).toContainEqual([
      "billing_rule.enterprise_id", "=", "unified_model.enterprise_id",
    ]);
    expect(trace.selections.flat()).toContain("billing_rule.id as billing_rule_id");
    expect(trace.comparisons).toEqual(expect.arrayContaining([
      ["principal_key.id", "=", "key"],
      ["principal_key.enterprise_id", "=", "enterprise"],
      ["principal_key.principal_id", "=", "principal"],
      ["principal_key.status", "=", "ACTIVE"],
      ["principal.status", "=", "ACTIVE"],
      ["model_route.provider_resource_id", "=", "resource"],
      ["model_route.upstream_model", "=", "kimi-k3"],
      ["billing_rule.enabled", "=", true],
      ["billing_rule.effective_from", "<=", now],
      ["billing_rule.effective_to", "is", null],
      ["billing_rule.effective_to", ">", now],
      ["billing_rule.provider_resource_id", "is", null],
      ["billing_rule.provider_resource_id", "=", { ref: "provider_resource.id" }],
      ["billing_rule.upstream_model", "is", null],
      ["billing_rule.upstream_model", "=", { ref: "model_route.upstream_model" }],
      ["provider_resource.mode", "=", "API"],
      ["billing_rule.rule_type", "=", "API_PRICE"],
      ["billing_rule.cache_hit_price", "is not", null],
      ["billing_rule.cache_miss_price", "is not", null],
      ["billing_rule.output_price", "is not", null],
      ["provider_resource.mode", "=", "CODING_PLAN"],
      ["billing_rule.rule_type", "in", ["TIME_WINDOW", "MODEL_TIER"]],
      ["billing_rule.multiplier", "is not", null],
      ["principal_grant.valid_from", "<=", now],
      ["principal_grant.valid_until", "is", null],
      ["principal_grant.valid_until", ">", now],
      ["principal_grant.pool_model_alias", "is", null],
      ["principal_grant.model_alias", "=", { ref: "unified_model.alias" }],
      ["principal_grant.pool_model_alias", "=", "*"],
      ["principal_provider_disabled_model.principal_id", "=", "principal"],
    ]));
  });

  it("fails closed for empty API prices and accepts every individual price field", async () => {
    const authorization = {
      allowed_model_ids: ["model-id"], expires_at: null, model_id: "model-id", resource_mode: "API",
    };
    for (const [field, expected] of [
      [null, false],
      ["cache_hit_price", true],
      ["cache_miss_price", true],
      ["output_price", true],
    ] as const) {
      const rule = {
        ...DEFAULT_BILLING_RULE,
        cache_hit_price: null,
        cache_miss_price: null,
        output_price: null,
        ...(field ? { [field]: "0.000001" } : {}),
      };
      const { db } = fakeDb(authorization, [rule]);
      await expect(hasCurrentInvocationAuthorization(db as never, AUTH_INPUT)).resolves.toBe(expected);
    }
  });

  it("applies CODING_PLAN multiplier windows instead of treating any rule as current", async () => {
    const authorization = {
      allowed_model_ids: ["model-id"], expires_at: null, model_id: "model-id",
      resource_mode: "CODING_PLAN",
    };
    const baseRule = {
      ...DEFAULT_BILLING_RULE,
      rule_type: "MODEL_TIER",
      multiplier: "1",
      cache_hit_price: null,
      cache_miss_price: null,
      output_price: null,
    };
    const allowed = fakeDb(authorization, [baseRule]);
    await expect(hasCurrentInvocationAuthorization(allowed.db as never, AUTH_INPUT)).resolves.toBe(true);

    const excluded = fakeDb(authorization, [{
      ...baseRule,
      rule_type: "TIME_WINDOW",
      days_of_week: [1],
      start_time: "00:00",
      end_time: "23:59",
    }]);
    await expect(hasCurrentInvocationAuthorization(excluded.db as never, AUTH_INPUT)).resolves.toBe(false);
  });

  it("fails closed for missing, expired and empty-model authorization and preserves rule windows", async () => {
    await expect(hasCurrentInvocationAuthorization(fakeDb(null).db as never, AUTH_INPUT))
      .resolves.toBe(false);
    await expect(hasCurrentInvocationAuthorization(fakeDb({
      allowed_model_ids: ["model-id"], expires_at: AUTH_INPUT.now,
      model_id: "model-id", resource_mode: "API",
    }).db as never, AUTH_INPUT)).resolves.toBe(false);
    await expect(hasCurrentInvocationAuthorization(fakeDb({
      allowed_model_ids: [], expires_at: null,
      model_id: "model-id", resource_mode: "API",
    }).db as never, AUTH_INPUT)).resolves.toBe(false);

    const futureExpiry = new Date(AUTH_INPUT.now.getTime() + 1);
    const window = {
      timezone: "Asia/Shanghai", days_of_week: [7],
      start_time: "19:00", end_time: "21:00",
    };
    const current = fakeDb({
      allowed_model_ids: ["model-id"], expires_at: futureExpiry,
      model_id: "model-id", resource_mode: "API",
    }, [{
      ...DEFAULT_BILLING_RULE,
      timezone: null, days_of_week: null, start_time: null, end_time: null,
      time_windows: [window],
    }]);
    await expect(getCurrentInvocationAuthorization(current.db as never, AUTH_INPUT))
      .resolves.toMatchObject({
        billingRule: {
          timeWindows: [{
            timezone: "Asia/Shanghai", daysOfWeek: [7],
            startTime: "19:00", endTime: "21:00",
          }],
        },
      });
  });
});

src/__tests-integration__/w16-dispatch.t.source:
import { describe, it, expect } from "vitest";
import { StubUpstream } from "@qianliu/provider-adapters";
import { resA, resB, ledgerRepo, dispatchRepo, ENT_ID, authHeader, buildApp, setStub } from "./w16-dispatch-fixture.js";

describe("W16 调度动作", () => {
  it("WT-16：高峰时段命中 SWITCH 策略 → 在等价资源组内切换（dispatch_decision 可解释）", async () => {
    // 发布高峰 SWITCH 策略：A → 等价组 [A,B] 内切换
    await dispatchRepo.createPolicy({
      enterpriseId: ENT_ID,
      status: "PUBLISHED",
      matchUnifiedModel: "ql-glm-5.2",
      matchPriceMultiplierMin: "3", // 高峰倍率 ≥3 命中
      matchResourceMode: "CODING_PLAN",
      matchProviderResourceId: null,
      matchTimezone: null,
      matchDaysOfWeek: null,
      matchStartTime: null,
      matchEndTime: null,
      matchRemainingQuotaRatioMax: null,
      matchForecastExhaustRisk: null,
      matchPrincipalScope: null,
      action: "SWITCH",
      switchEquivalentGroup: [resA, resB],
      rateLimitPerMinute: null,
      policyVersion: "w16-v1",
      priority: 100,
    });

    // StubUpstream 成功；resolveDispatchInput 注入高峰倍率 3（命中策略）
    setStub(new StubUpstream({
      default: { kind: "SUCCESS", usage: { input: 500, output: 200, cache: 0 } },
      providerCode: "zhipu",
    }));
    const app = await buildApp(async () => ({
      priceMultiplier: "3", // 高峰
      remainingQuotaRatio: 0.8,
      forecastExhaustRisk: false,
    }));

    const chatRes = await app.inject({
      method: "POST",
      url: "/v1/chat/completions",
      headers: authHeader(),
      payload: { model: "ql-glm-5.2", messages: [{ role: "user", content: "hi" }] },
    });
    expect(chatRes.statusCode).toBe(200);
    const requestId = chatRes.headers["x-request-id"];
    await app.close();

    // dispatch_decision：final_action=SWITCH，目标=resB
    const decision = await dispatchRepo.getDecision(requestId);
    expect(decision).toBeDefined();
    expect(decision!.final_action).toBe("SWITCH");
    expect(decision!.reason_code).toBe("SWITCH_WITHIN_GROUP");
    expect(decision!.switch_target_resource_id).toBe(resB);

    // 实际 Attempt 落到 resB（切换后的资源）
    const attempts = await ledgerRepo.listAttempts(requestId);
    expect(attempts[0]!.provider_resource_id).toBe(resB);
  });

  it("WT-16：命中 REJECT 策略 → 403（不无账放行）", async () => {
    // REJECT 策略：剩余额度比例 ≤0.1 命中
    await dispatchRepo.createPolicy({
      enterpriseId: ENT_ID,
      status: "PUBLISHED",
      matchUnifiedModel: "ql-glm-5.2",
      matchRemainingQuotaRatioMax: "0.1",
      matchResourceMode: null,
      matchProviderResourceId: null,
      matchTimezone: null,
      matchDaysOfWeek: null,
      matchStartTime: null,
      matchEndTime: null,
      matchPriceMultiplierMin: null,
      matchForecastExhaustRisk: null,
      matchPrincipalScope: null,
      action: "REJECT",
      switchEquivalentGroup: null,
      rateLimitPerMinute: null,
      policyVersion: "w16-v1",
      priority: 50, // 比 SWITCH 更高优先级
    });

    setStub(new StubUpstream({
      default: { kind: "SUCCESS", usage: { input: 100, output: 50, cache: 0 } },
      providerCode: "zhipu",
    }));
    const app = await buildApp(async () => ({
      priceMultiplier: "1",
      remainingQuotaRatio: 0.05, // 命中 REJECT（≤0.1）
      forecastExhaustRisk: false,
    }));

    const chatRes = await app.inject({
      method: "POST",
      url: "/v1/chat/completions",
      headers: authHeader(),
      payload: { model: "ql-glm-5.2", messages: [{ role: "user", content: "hi" }] },
    });
    expect(chatRes.statusCode).toBe(403);
    expect(chatRes.json().error).toEqual(expect.objectContaining({
      code: "dispatch_rejected",
      dispatch: {
        final_action: "REJECT",
        reason_code: "REJECTED",
        policy_version: "w16-v1",
      },
    }));
    expect(chatRes.json().error.dispatch).not.toHaveProperty("unavailable_window");
    const requestId = chatRes.headers["x-request-id"];
    await app.close();

    const decision = await dispatchRepo.getDecision(requestId);
    expect(decision).toEqual(expect.objectContaining({
      matched_policy_action: "REJECT",
      final_action: "REJECT",
      reason_code: "REJECTED",
      saving_calculable: false,
      not_calculable_reason: "dispatch_terminated_before_attempt",
    }));
  });

  it("WT-16：命中 RATE_LIMIT 策略 → 429", async () => {
    await dispatchRepo.createPolicy({
      enterpriseId: ENT_ID,
      status: "PUBLISHED",
      matchUnifiedModel: "ql-glm-5.2",
      matchForecastExhaustRisk: true, // 预计耗尽风险命中
      matchResourceMode: null,
      matchProviderResourceId: null,
      matchTimezone: null,
      matchDaysOfWeek: null,
      matchStartTime: null,
      matchEndTime: null,
      matchPriceMultiplierMin: null,
      matchRemainingQuotaRatioMax: null,
      matchPrincipalScope: null,
      action: "RATE_LIMIT",
      switchEquivalentGroup: null,
      rateLimitPerMinute: 10,
      policyVersion: "w16-v1",
      priority: 40,
    });

    setStub(new StubUpstream({
      default: { kind: "SUCCESS", usage: { input: 100, output: 50, cache: 0 } },
      providerCode: "zhipu",
    }));
    const app = await buildApp(async () => ({
      priceMultiplier: "1",
      remainingQuotaRatio: 0.5,
      forecastExhaustRisk: true, // 命中 RATE_LIMIT
    }));

    const chatRes = await app.inject({
      method: "POST",
      url: "/v1/chat/completions",
      headers: authHeader(),
      payload: { model: "ql-glm-5.2", messages: [{ role: "user", content: "hi" }] },
    });
    expect(chatRes.statusCode).toBe(429);
    expect(chatRes.json().error).toEqual(expect.objectContaining({
      message: "经营调度限流",
      code: "dispatch_rate_limited",
      dispatch: {
        final_action: "RATE_LIMIT",
        reason_code: "RATE_LIMITED",
        policy_version: "w16-v1",
      },
    }));
    const requestId = chatRes.headers["x-request-id"];
    await app.close();

    expect(await dispatchRepo.getDecision(requestId)).toEqual(expect.objectContaining({
      matched_policy_action: "RATE_LIMIT",
      final_action: "RATE_LIMIT",
      reason_code: "RATE_LIMITED",
      saving_calculable: false,
      not_calculable_reason: "dispatch_terminated_before_attempt",
    }));
  });

  it("WT-17：无策略/ALLOW 仅提示 → saving_calculable=false（NOT_CALCULABLE）", async () => {
    // 该请求无任何高风险输入 → 不命中 REJECT/RATE_LIMIT/SWITCH → 默认 ALLOW_NO_POLICY
    setStub(new StubUpstream({
      default: { kind: "SUCCESS", usage: { input: 300, output: 100, cache: 0 } },
      providerCode: "zhipu",
    }));
    const app = await buildApp(async () => ({
      priceMultiplier: "1",
      remainingQuotaRatio: 0.9, // 充足，不命中任何策略
      forecastExhaustRisk: false,
    }));

    const chatRes = await app.inject({
      method: "POST",
      url: "/v1/chat/completions",
      headers: authHeader(),
      payload: { model: "ql-glm-5.2", messages: [{ role: "user", content: "hi" }] },
    });
    expect(chatRes.statusCode).toBe(200);
    const requestId = chatRes.headers["x-request-id"];
    await app.close();

    const decision = await dispatchRepo.getDecision(requestId);
    expect(decision!.final_action).toBe("ALLOW");
    expect(decision!.reason_code).toBe("ALLOW_NO_POLICY");
    // ALLOW 仅提示，未改变行为 → NOT_CALCULABLE（行 631）
    expect(decision!.saving_calculable).toBe(false);
    expect(decision!.not_calculable_reason).toBe("no_action_executed");
    expect(decision!.dispatch_saving).toBeNull();
  });
});

